static inline unsigned int emoji_rgi_first_scalar(const WCHAR *text, int count)
{
    if (count > 1 && text[0] >= 0xd800 && text[0] <= 0xdbff &&
        text[1] >= 0xdc00 && text[1] <= 0xdfff)
        return 0x10000 + ((text[0] - 0xd800) << 10) + text[1] - 0xdc00;
    return text[0];
}

static inline int emoji_rgi_match_utf16(const WCHAR *text, int count)
{
    unsigned int first, lo = 0, hi = ARRAY_SIZE(emoji_rgi_sequences), mid, j;
    if (count < 2) return 0;
    first = emoji_rgi_first_scalar(text, count);
    while (lo < hi)
    {
        mid = lo + (hi - lo) / 2;
        if (emoji_rgi_sequences[mid].first < first) lo = mid + 1; else hi = mid;
    }
    while (lo < ARRAY_SIZE(emoji_rgi_sequences) && emoji_rgi_sequences[lo].first == first)
    {
        const struct emoji_rgi_sequence *seq = &emoji_rgi_sequences[lo++];
        if (seq->length > count) continue;
        for (j = 0; j < seq->length; ++j) if (text[j] != emoji_rgi_data[seq->offset + j]) break;
        if (j == seq->length) return seq->length;
    }
    return 0;
}

